-- Name: news_news_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.news_news ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.news_news_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: offers_offer; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.offers_offer (
    id uuid NOT NULL,
    title character varying(250),
    description text,
    banner_image character varying(100),
    published_date timestamp with time zone NOT NULL,
    discount_percent double precision,
    discounted_price double precision,
    active boolean NOT NULL,
    begin_date date,
    end_date date,
    provider_id uuid NOT NULL,
    description_ca text,
    description_es text,
    description_eu text,
    description_gl text,
    title_ca character varying(250),
    title_es character varying(250),
    title_eu character varying(250),
    title_gl character varying(250)
);


ALTER TABLE public.offers_offer OWNER TO postgres;

